// Shared with Achille's website chat, so the app and the website behave
// alike. Generated by scripts/sync-shared.mjs: do not edit it here.

// The visitor's conversations on a ticketing chat (mode "human"). The session
// token names the VISITOR; each of their tickets on the chat is one
// conversation (GET /widget_api/v1/conversations, newest activity first). The
// widget shows them in the Messages tab, opens one at a time, and can start a
// new one. Pure functions: no React, no network.

export interface LastMessage {
  body: string;
  from_agent: boolean;
  sender_name: string | null;
  created_at: string;
  attachments_count: number;
}

export interface ConversationSummary {
  id: string;
  status: "open" | "closed";
  // The server would still continue it (open, or closed within its reopen
  // window). false: read-only, a new message needs a new conversation.
  can_reply: boolean;
  typing: boolean;
  unread: number;
  updated_at: string;
  last_message: LastMessage | null;
}

export interface ConversationList {
  conversations: ConversationSummary[];
  unread: number;
  sessionEnded: boolean;
}

// The conversation a ticketing backend without the list knows: the visitor's
// latest ticket, asked for without a conversation id (see legacyConversation).
export const LATEST = "latest";

type Raw = Record<string, unknown>;

function isRecord(value: unknown): value is Raw {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function count(value: unknown): number {
  return typeof value === "number" && Number.isFinite(value) && value > 0 ? Math.floor(value) : 0;
}

function parseLastMessage(raw: unknown): LastMessage | null {
  if (!isRecord(raw)) return null;
  return {
    body: typeof raw.body === "string" ? raw.body : "",
    from_agent: raw.from_agent === true,
    sender_name: typeof raw.sender_name === "string" && raw.sender_name ? raw.sender_name : null,
    created_at: typeof raw.created_at === "string" ? raw.created_at : "",
    attachments_count: count(raw.attachments_count),
  };
}

function parseConversation(raw: unknown): ConversationSummary | null {
  if (!isRecord(raw)) return null;
  const id = typeof raw.id === "string" || typeof raw.id === "number" ? String(raw.id) : "";
  if (!id) return null;
  const lastMessage = parseLastMessage(raw.last_message);
  return {
    id,
    status: raw.status === "closed" ? "closed" : "open",
    can_reply: raw.can_reply !== false,
    typing: raw.typing === true,
    unread: count(raw.unread),
    updated_at: typeof raw.updated_at === "string" ? raw.updated_at : lastMessage?.created_at ?? "",
    last_message: lastMessage,
  };
}

function time(iso: string): number {
  const value = Date.parse(iso);
  return Number.isNaN(value) ? 0 : value;
}

// Newest activity first. The server already sorts; a list that arrives in
// another order (or with equal times) still reads the same on every poll.
export function sortConversations(list: readonly ConversationSummary[]): ConversationSummary[] {
  return [...list].sort((a, b) => time(b.updated_at) - time(a.updated_at) || (a.id < b.id ? 1 : -1));
}

// The list poll's payload, or null when it is not one.
export function parseConversationList(raw: unknown): ConversationList | null {
  if (!isRecord(raw)) return null;
  if (raw.session_ended === true) return { conversations: [], unread: 0, sessionEnded: true };
  if (!Array.isArray(raw.conversations)) return null;
  const conversations = sortConversations(
    raw.conversations.map(parseConversation).filter((c): c is ConversationSummary => c !== null)
  );
  return { conversations, unread: totalUnread(raw.unread, conversations), sessionEnded: false };
}

// The badges' count: the server's total, else the sum of the rows.
export function totalUnread(total: unknown, conversations: readonly ConversationSummary[]): number {
  if (typeof total === "number" && Number.isFinite(total) && total >= 0) return Math.floor(total);
  return conversations.reduce((sum, c) => sum + c.unread, 0);
}

// A tab badge stays small: "9+" past nine, nothing at zero.
export function badgeText(unread: number): string | null {
  if (unread <= 0) return null;
  return unread > 9 ? "9+" : String(unread);
}

// A backend without the list (404): the latest ticket's thread (GET /messages
// without a conversation id) stands in for a list of one, so the home screen
// and the Messages tab still lead back to it. null without a message.
export function legacyConversation(raw: unknown): ConversationSummary | null {
  if (!isRecord(raw) || !Array.isArray(raw.messages)) return null;
  const last = raw.messages[raw.messages.length - 1];
  if (!isRecord(last)) return null;
  const attachments = Array.isArray(last.attachments) ? last.attachments.length : 0;
  const lastMessage = parseLastMessage({ ...last, attachments_count: attachments });
  return {
    id: LATEST,
    status: "open",
    can_reply: true,
    typing: raw.typing === true,
    unread: 0,
    updated_at: lastMessage?.created_at ?? "",
    last_message: lastMessage,
  };
}

// ---------------------------------------------------------------------------
// What a row shows

export interface RowStrings {
  you: string;
  attachment: string;
  attachments: string;
  justNow: string;
  minutes: string;
  hours: string;
  yesterday: string;
}

// Agent replies are markdown (links, bold); a one-line preview shows their
// words only. An order number's "#" or an email's "_" stays.
export function plainText(markdown: string): string {
  return markdown
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, "$1")
    .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
    .replace(/(\*\*|__)(.+?)\1/g, "$2")
    .replace(/(^|[^\w*])[*_](?=\S)([^*_\n]*?\S)[*_](?![\w*])/g, "$1$2")
    .replace(/`+/g, "")
    .replace(/^\s{0,3}(#{1,6}|>|[-*+])\s+/gm, "")
    .replace(/\s+/g, " ")
    .trim();
}

export interface Preview {
  // "Vous : " when the visitor wrote it.
  prefix: string;
  text: string;
  // Files only: the row shows a paperclip before the text.
  files: boolean;
}

export function previewOf(conversation: ConversationSummary, strings: RowStrings): Preview {
  const message = conversation.last_message;
  if (!message) return { prefix: "", text: "", files: false };
  const prefix = message.from_agent ? "" : strings.you;
  const text = plainText(message.body);
  if (text || message.attachments_count === 0) return { prefix, text, files: false };
  const files =
    message.attachments_count === 1
      ? strings.attachment
      : strings.attachments.replace("{count}", String(message.attachments_count));
  return { prefix, text: files, files: true };
}

// Who the row is from: the agent who wrote the last reply, else the chat.
export function rowName(conversation: ConversationSummary, chatName: string): string {
  const message = conversation.last_message;
  return (message?.from_agent && message.sender_name) || chatName;
}

function sameDay(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

// "À l'instant", "5 min", "2 h", "Hier", then a short date in the visitor's
// language ("12 oct.", with the year when it is not this one).
export function relativeTime(iso: string, now: Date, lang: string, strings: RowStrings): string {
  const at = new Date(iso);
  if (Number.isNaN(at.getTime())) return "";
  const minutes = Math.floor((now.getTime() - at.getTime()) / 60_000);
  if (minutes < 1) return strings.justNow;
  if (minutes < 60) return strings.minutes.replace("{n}", String(minutes));
  if (minutes < 24 * 60) return strings.hours.replace("{n}", String(Math.floor(minutes / 60)));
  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  if (sameDay(at, yesterday)) return strings.yesterday;
  const options: Intl.DateTimeFormatOptions = { day: "numeric", month: "short" };
  if (at.getFullYear() !== now.getFullYear()) options.year = "numeric";
  try {
    return at.toLocaleDateString([lang], options);
  } catch {
    return at.toLocaleDateString([], options);
  }
}

// ---------------------------------------------------------------------------
// Navigation

export type Screen = "home" | "messages" | "conversation";

export type Target = { kind: "home" } | { kind: "new" } | { kind: "open"; id: string };

// Where the list stands: not answered yet, answered, replaced by the latest
// ticket (a backend without it), unreachable, or not asked (a preview).
export type ListStatus = "pending" | "ready" | "legacy" | "failed" | "off";

// Where the chat opens. A chat with a home screen: there. Else the most recent
// conversation the visitor can still write in, or a new one; a visitor with a
// token waits for the list (null), and without a list goes back to their
// latest ticket, as before.
export function landingTarget(o: {
  hasHome: boolean;
  hasToken: boolean;
  status: ListStatus;
  conversations: readonly ConversationSummary[];
}): Target | null {
  if (o.hasHome) return { kind: "home" };
  if (!o.hasToken) return { kind: "new" };
  if (o.status === "pending") return null;
  if (o.status === "failed" || o.status === "off") return { kind: "open", id: LATEST };
  const open = o.conversations.find((c) => c.can_reply);
  return open ? { kind: "open", id: open.id } : { kind: "new" };
}

// Where the conversation's back arrow goes: where the visitor came from on a
// chat with a home screen; else the Messages list once there is something in
// it (none: no arrow).
export function backTarget(o: {
  hasHome: boolean;
  cameFrom: "home" | "messages" | null;
  conversationCount: number;
}): "home" | "messages" | null {
  if (o.hasHome) return o.cameFrom ?? "home";
  return o.conversationCount > 0 ? "messages" : null;
}

// Where a question from the storefront (product page box, teaser) goes: the
// conversation on screen when it can take it, else the most recent open one,
// else a new one.
export function askTarget(o: {
  onConversation: boolean;
  canReply: boolean;
  conversations: readonly ConversationSummary[];
}): { kind: "current" } | { kind: "new" } | { kind: "open"; id: string } {
  if (o.onConversation && o.canReply) return { kind: "current" };
  const open = o.conversations.find((c) => c.status === "open" && c.can_reply);
  return open ? { kind: "open", id: open.id } : { kind: "new" };
}

// ---------------------------------------------------------------------------
// Sound

// Conversations whose unread count went up since the previous poll, other
// than the one on screen (its own poll rings for it). The first poll is
// history (`previous` null): nothing rings.
export function listRings(
  previous: ReadonlyMap<string, number> | null,
  conversations: readonly ConversationSummary[],
  openId: string | null
): ConversationSummary[] {
  if (!previous) return [];
  return conversations.filter((c) => c.id !== openId && c.unread > (previous.get(c.id) ?? 0));
}

export function unreadById(conversations: readonly ConversationSummary[]): Map<string, number> {
  return new Map(conversations.map((c) => [c.id, c.unread]));
}

// One reply rings once, whichever poll saw it first (the open conversation's
// or the list's).
export function ringKey(conversationId: string, createdAt: string): string {
  return `${conversationId}|${createdAt}`;
}
